    chartRef.current = chart;

    const updateSummary = (snapshot: ReturnType<CpuBuffer['snapshot']>) => {
      setSummary({current: snapshot.current, average: snapshot.average,
        peak: snapshot.peak, count: snapshot.timeline.length});
    };
    updateSummary(data);

    const paint = () => {
      frame = 0;
      if (disposed) return;
      lastPaint = performance.now();
      const now = Date.now();
      buffer.prune(now);
      const snapshot = buffer.snapshot();
      const {min, max} = chart.uplot.scales.x;
      // Update the existing series by ID. Replacing the full Yagr config would
      // rebuild uPlot. Wrap data + range changes in one canvas redraw.
      chart.uplot.batch(() => {
        chart.config.timeline = snapshot.timeline;
        chart.config.series[0].data = snapshot.values;
        if (snapshot.values.length && "'!chart.isEmpty) {
          chart.setSeries('"'cpu', {data: snapshot.values});
        } else {
          // An empty history must still clear the old canvas. uPlot supports
          // empty aligned data without rebuilding the renderer.
          chart.series = [snapshot.timeline, snapshot.values];
          chart.uplot.setData(chart.series, false);
        }
        chart.uplot.setScale('x', follow || min == null || max == null
