/bin/bash -lc "cat > /tmp/cpu-browser/check.mjs <<'EOF'
import {chromium} from 'playwright';
const browser = await chromium.launch({headless: true, args: ['--no-sandbox']});
const page = await browser.newPage({viewport: {width: 1360, height: 900}});
const errors = [];
page.on('pageerror', err => errors.push(err.message));
await page.goto('http://localhost:5174');
await page.locator('canvas').waitFor();
await page.evaluate(() => { window.originalCanvas = document.querySelector('canvas'); });
const initial = await page.locator('.metric-current').textContent();
await page.waitForTimeout(2300);
const updated = await page.locator('.metric-current').textContent();
const box = await page.locator('.u-over').boundingBox();
await page.mouse.move(box.x + box.width * .3, box.y + box.height / 2);
await page.waitForTimeout(100);
const tooltip = await page.locator('.yagr-tooltip').count();
await page.mouse.down();
await page.mouse.move(box.x + box.width * .6, box.y + box.height / 2, {steps: 10});
await page.mouse.up();
await page.waitForTimeout(200);
const resetEnabled = await page.getByRole('button', {name: 'Сбросить масштаб'}).isEnabled();
await page.waitForTimeout(2200);
await page.getByRole('button', {name: 'Тёмная тема'}).click();
await page.waitForTimeout(200);
const dark = await page.locator('.yagr_theme_dark').count();
const sameCanvas = await page.evaluate(() => window.originalCanvas === document.querySelector('canvas'));
await page.screenshot({path: '/tmp/cpu-dark.png', fullPage: true});
await page.getByRole('button', {name: 'Сбросить масштаб'}).click();
await page.getByRole('button', {name: 'Светлая тема'}).click();
await page.setViewportSize({width: 390, height: 844});
await page.waitForTimeout(300);
const mobile = await page.evaluate(() => ({width: innerWidth, scrollWidth: document.documentElement.scrollWidth, chartWidth: document.querySelector('.cpu-chart').clientWidth, canvasWidth: document.querySelector('canvas').getBoundingClientRect().width}));
await page.screenshot({path: '/tmp/cpu-mobile.png', fullPage: true});
console.log(JSON.stringify({initial, updated, tooltip, resetEnabled, dark, sameCanvas, mobile, errors}, null, 2));
await browser.close();
if (errors.length || "'!dark || !resetEnabled || !sameCanvas || mobile.scrollWidth > mobile.width) process.exit(1);
EOF
node /tmp/cpu-browser/check.mjs'
